// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        vm.startPrank(caller);
        try c.owned() {} catch {}
        try c.burn(burnAmount) {} catch {}
        vm.stopPrank();
        assertTrue(c.owner() == address(this));
    }
}
